def is_graphic(seq):
    seq=sorted(seq, reverse=True)
    while seq and seq[0]==0:
        seq.pop(0)
    while seq:
        d=seq.pop(0)
        if d>len(seq):
            return False
        for i in range(d):
            seq[i]-=1
            if seq[i]<0:
                return False
        seq=sorted(seq, reverse=True)
    return True
seq=[5]*6+[4]*7
print(is_graphic(seq))
